# cc-P266 WRITES server/customizations/ClusterFWinterDecorLayout.cs from placement.json, after validate.py passes (it
# refuses to write while any row fails). The same record shape as P34's generated file (Key, Area, X, Y, Z, ItemId,
# Name, Hue, Facing, Layer), the same spawner-tile list (every pinned Distribution/Data/Spawns entry on Trammel in
# the box, and our healer spawner), plus RegisteredIds: every winter art ID registry.csv holds (P34's block and this
# set's), so the server's test can refuse a row whose ID nobody registered.
import json, os, sys, subprocess, csv, glob
HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import art_src as S
SL = 'D:/UO/golems/Bronze/ShatteredLegacy'
OUT = SL + '/server/customizations/ClusterFWinterDecorLayout.cs'
REG = SL + '/player-package/vendor/shattered-legacy-art/registry.csv'
PINNED = 'D:/UO/ModernUO-pinned'
BOX = (3400, 2460, 3560, 2660)
r = subprocess.run([sys.executable, '-P', os.path.join(HERE, 'validate.py')], capture_output=True, text=True)
if r.returncode:
    sys.exit('validate.py fails; not writing:\n' + r.stdout[-3000:])
rows = json.load(open(os.path.join(HERE, 'placement.json')))
reg = sorted(int(x['id']) for x in csv.DictReader(l for l in open(REG, encoding='ascii') if not l.startswith('#'))
             if x['kind'] == 'art' and (S.P34_FIRST <= int(x['id']) <= S.P34_LAST or S.FIRST <= int(x['id']) <= S.LAST))
HUE = {0x8E2: 0x481, 0x8E0: 0x481, 0x8E6: 0x481, 0x8E5: 0x481, 0x8E3: 0x481}   # pinned SnowPileDeco: Hue = 0x481

# P34's spawner list: every pinned Spawns entry (all folders, as P34 read them) on Trammel in the box, plus the healer
sp = {(3462, 2559)}
for f in glob.glob(PINNED + '/Distribution/Data/Spawns/**/*.json', recursive=True):
    try: d = json.load(open(f, encoding='utf-8-sig'))
    except Exception: continue
    for e in d if isinstance(d, list) else []:
        loc = e.get('location')
        if e.get('map') == 'Trammel' and loc and BOX[0] <= loc[0] <= BOX[2] and BOX[1] <= loc[1] <= BOX[3]:
            sp.add((loc[0], loc[1]))
sp = sorted(sp)


def cs(s): return '"' + s.replace('\\', '\\\\').replace('"', '\\"') + '"'


out = [
    '// GENERATED by shard-migration notes/cc-P266-tools/gen_layout.py from placement.json. Do not edit by hand:',
    '// change placement.json (draft.py writes it), run validate.py (the map checks), then gen_layout.py.',
    '//',
    '// cc-P34 and cc-P266 (F-22): the winter decor for New Haven, one row per item, all on Trammel. Every row was checked',
    '// against the server\'s own map files: surface z, nothing impassable in the way, not a road (outside the square, the',
    '// pier and a wall\'s foot), not a door, door swing, NPC post, spawner tile or ring, a seeded tile of another seeder',
    '// (P237\'s community art, P267\'s Halloween rows), the arrival tile or the Reset Stone; wall art only in front of a',
    '// north or west wall (the faces the client shows). The table with a reason per row is in the cc-P266 notes.',
    '// Layer: osi (stock art), community (our package\'s art), calendar (the advent calendar: a WinterAdventCalendar, not a',
    '// WinterDecor, placed and tracked the same way).',
    '',
    'namespace Server;',
    '',
    'public static class ClusterFWinterDecorLayout',
    '{',
    '    public sealed record Row(string Key, string Area, int X, int Y, int Z, int ItemId, string Name, int Hue, string Facing, string Layer);',
    '',
    '    public static readonly Row[] Rows =',
    '    {',
]
for x in rows:
    out.append('        new(%s, %s, %d, %d, %d, 0x%04X, %s, 0x%03X, %s, %s),' % (cs(x['key']), cs(x['area']), x['x'], x['y'], x['z'], x['itemId'], cs(x['name']),
                                                                             HUE.get(x['itemId'], 0), cs(x['facing']), cs(x['layer'])))
out += [
    '    };',
    '',
    '    // Every pinned Distribution/Data/Spawns entry on Trammel inside x3400-3560, y2460-2660, and our healer spawner.',
    '    // No row may sit on one (the test reads this list; a spawner placed later is not in it).',
    '    public static readonly (int X, int Y)[] SpawnerTiles =',
    '    {',
]
for i in range(0, len(sp), 8):
    out.append('        ' + ' '.join('(%d, %d),' % t for t in sp[i:i + 8]))
out += [
    '    };',
    '',
    '    // The winter art IDs registry.csv registers (%d: P34\'s 0x%04X-0x%04X and P266\'s 0x%04X-0x%04X): a row may use only' % (len(reg), S.P34_FIRST, S.P34_LAST, S.FIRST, S.LAST),
    '    // these or an OSI holiday ID.',
    '    public static readonly int[] RegisteredIds =',
    '    {',
]
for k in range(0, len(reg), 8):
    out.append('        ' + ', '.join('0x%04X' % i for i in reg[k:k + 8]) + ',')
out += ['    };', '}', '']
open(OUT, 'w', encoding='ascii', newline='\n').write('\n'.join(out))
print('wrote', OUT, len(rows), 'rows,', len(sp), 'spawner tiles,', len(reg), 'registered IDs')
